-- PT109-S3-Q22. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT109-S3-Q22$batch12$ AND q.stimulus=$batch12$If relativity theory is correct, no object can travel forward in time at a speed greater than the speed of light. Yet quantum mechanics predicts that the tachyon, a hypothetical subatomic particle, travels faster than light. Thus, if relativity theory is correct, either quantum mechanics’ prediction about tachyons is erroneous or tachyons travel backward in time.$batch12$ AND q.prompt=$batch12$The pattern of reasoning in which one of the following arguments is most similar to that in the argument above?$batch12$ AND q.correct_choice=$batch12$C$batch12$) THEN RAISE EXCEPTION 'Question changed: PT109-S3-Q22'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT109-S3-Q22$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S3-Q22'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT109-S3-Q22$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$If relativity is correct, either the tachyon prediction is wrong or tachyons travel backward in time.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Relativity says nothing can travel forward in time faster than light. Quantum mechanics predicts tachyons travel faster than light.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$A trusted theory rules something out. A source says it happened. So if the theory holds, either the source is wrong or the case escapes the rule's condition ("forward in time").$batch12$), (3, $batch12$Goal$batch12$, $batch12$Theory forbids X; a report says X; so if the theory holds, the report is wrong or the case falls outside the rule.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT109-S3-Q22$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This prefers one origin theory over another. No conditional conclusion with two options.$batch12$), ($batch12$B$batch12$, $batch12$This concludes the defendant is guilty, a flat verdict.$batch12$), ($batch12$C$batch12$, $batch12$The brain can't survive long without oxygen. A witness says the shaman survived a week buried. So if medicine is right, the witness is wrong or the brain didn't lack oxygen. Same structure.$batch12$), ($batch12$D$batch12$, $batch12$This weighs evidence between two burial sites.$batch12$), ($batch12$E$batch12$, $batch12$This draws a prediction from a theory. No conflict between a theory and a report.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT109-S3-Q22$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
